+  text-align: left;
+}
+ 
+table thead {
+  border-bottom: 2px solid #eee;
+}
+ 
+table th {
+  padding: 1rem;
+  color: var(--nav-link-color);
+  font-weight: 600;
+  text-transform: uppercase;
+  font-size: 0.85rem;
+}
+ 
+table td {
+  padding: 1rem;
+  border-bottom: 1px solid #eee;
+  color: var(--color-dark);
+}
+ 
+table tbody tr:last-child td {
+  border-bottom: none;
+}
+ 
+table .actions {
+  display: flex;
+  align-items: center;
+  gap: 1rem;
+}
+ 
+table .actions a,
+table .actions .delete-button {
+  color: var(--nav-link-color);
+  font-size: 1.2rem;
+  text-decoration: none;
+}
+ 
+table .actions a:hover,
+table .actions .delete-button:hover {
+  color: var(--color-primary);
+}
+ 
+/* Estilos do Modal */
+.modal {
+  display: none; /* Oculto por padrão */
+  position: fixed;
+  z-index: 1000;
+  left: 0;
+  top: 0;
+  width: 100%;
+  height: 100%;
+  overflow: auto;
+  background-color: rgba(0, 0, 0, 0.5);
+  justify-content: center;
+  align-items: center;
+}
+ 
+.modal-content {
+  background-color: #fff;
+  margin: auto;
+  padding: 2rem;
+  border-radius: 0.5rem;
+  width: 90%;
+  max-width: 600px; /* Aumentado para acomodar campos lado a lado */
+  animation: slide-down 0.3s ease-out;
+}
+ 
+.modal-header {
+  display: flex;
+  justify-content: space-between;
+  align-items: center;
+  border-bottom: 1px solid #eee;
+  padding-bottom: 1rem;
+  margin-bottom: 1.5rem;
+}
+ 
+.modal-header h2 {
+  margin: 0;
+  font-size: 1.5rem;
+  color: var(--color-dark);
+}
+ 
+.close-button {
+  font-size: 2rem;
+  font-weight: bold;
+  border: none;
+  background: none;
+  cursor: pointer;
+  color: #aaa;
+}
+ 
+.modal-form .form-group {
+  margin-bottom: 1.5rem;
+}
+ 
+.modal-form label {
+  display: block;
+  margin-bottom: 0.5rem;
+  font-weight: 500;
+  color: var(--color-dark);
+}
+ 
+.modal-form input,
+.modal-form select {
+  width: 100%;
+  padding: 0.8rem;
+  border: 1px solid #ccc;
+  border-radius: 0.3rem;
+  background-color: white; /* Garante fundo branco para o select */
+  box-sizing: border-box;
+}
+ 
+/* Estilo para agrupar campos lado a lado */
+.modal-form .form-row {
+  display: flex;
+  gap: 1rem;
+  align-items: flex-start;
+}
+ 
+/* Garante que os grupos dentro da linha ocupem o espaço corretamente */
+.modal-form .form-row .form-group {
+  flex: 1;
+}
+ 
+.form-actions {
+  text-align: right;
+  margin-top: 2rem;
+}
+ 
+/* Estilo para o botão de exclusão parecer um ícone */
+.delete-button {
+  background: none;
+  border: none;
+  cursor: pointer;
+  padding: 0;
+  line-height: 1;
+}
+ 
+/* Estilos para o Modal de Confirmação de Exclusão */
+.modal-body {
+  padding: 1rem 0;
+  font-size: 1.1rem;
+  line-height: 1.6;
+  color: var(--nav-link-color);
+}
+ 
+.modal-body p {
+  margin: 0 0 0.5rem 0;
+}
+ 
+.modal-footer {
+  display: flex;
+  justify-content: flex-end; /* Alinha os botões à direita */
+  gap: 1rem; /* Espaçamento entre os botões */
+  padding-top: 1rem;
+  border-top: 1px solid #eee;
+  margin-top: 1.5rem;
+}
+ 
+.modal-footer .btn {
+  padding: 0.75rem 1.5rem;
+  font-size: 1rem;
+}
+ 
+/* Animação do modal */
+@keyframes slide-down {
+  from {
+    transform: translateY(-50px);
+    opacity: 0;
+  }
+  to {
+    transform: translateY(0);
+    opacity: 1;
+    
+
+@keyframes slide-down {
+  from {
+    transform: translateY(-50px);
+    opacity: 0;
+  }
+  to {
+    transform: translateY(0);
+    opacity: 1;
+  }
+}

